#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Purpose: create the SQS queues for the async receipt pipeline (ADR 0001) in
# one environment, plus the IAM policy the backend needs. Every step is
# confirmed before anything is created. Full notes, including how to do the
# same by hand in the AWS console: docs/sqs-provisioning.md
#
# Run it with ADMIN credentials (your own profile, e.g. AWS_PROFILE=admin),
# not with the backend's access key. Safe to re-run: existing queues are kept.

run_wizard() {

TOTAL_STAGES=8

# Fixed by the design, see docs/sqs-provisioning.md.
MAX_RECEIVE_COUNT=3
LONG_POLL_SECONDS=20
MAIN_RETENTION_SECONDS=345600   # 4 days
DLQ_RETENTION_SECONDS=1209600   # 14 days
DEFAULT_VISIBILITY_TIMEOUT=120  # seconds

aws_cli() { aws --region "$AWS_REGION" "$@"; }

die() { printf '\n  %s✗ %s%s\n\n' "$YELLOW" "$1" "$RESET"; exit 1; }

# queue_url NAME prints the queue's URL, or nothing if it does not exist.
queue_url() {
  aws_cli sqs get-queue-url --queue-name "$1" --query QueueUrl --output text 2>/dev/null || true
}

# create_queue NAME ATTRIBUTES_JSON confirms, creates the queue unless it
# already exists, and sets CREATED_URL and CREATED_ARN.
create_queue() {
  local name="$1" attributes="$2" url
  url=$(queue_url "$name")
  if [[ -n "$url" ]]; then
    warn "Queue $name already exists, so nothing is created."
    note "Compare its settings with the list above (console: open the queue, Details tab),"
    note "or run: aws sqs get-queue-attributes --queue-url $url --attribute-names All"
  else
    confirm "Create queue $name in $AWS_REGION now?" \
      || die "Not created. Nothing further was changed; re-run when ready."
    url=$(aws_cli sqs create-queue --queue-name "$name" --attributes "$attributes" \
      --query QueueUrl --output text)
    printf '  %s✓ created%s %s\n' "$GREEN" "$RESET" "$name"
  fi
  CREATED_URL="$url"
  CREATED_ARN=$(aws_cli sqs get-queue-attributes --queue-url "$url" \
    --attribute-names QueueArn --query Attributes.QueueArn --output text)
  say "URL: $CREATED_URL"
  say "ARN: $CREATED_ARN"
  pause "Press Enter for the next stage"
}

show_dlq_settings() {
  say "Type:                          Standard"
  say "Message retention period:      14 days ($DLQ_RETENTION_SECONDS s), longer than the source queue"
  say "Server-side encryption:        Enabled, Amazon SQS key (SSE-SQS)"
  say "Everything else:               console defaults (visibility 30 s, delay 0, 256 KB,"
  say "                               receive wait 0, access policy: queue owner only,"
  say "                               redrive allow policy: allow all)"
  say "No consumer reads this queue; failed messages wait here for inspection."
}

show_main_settings() {
  say "Type:                          Standard"
  say "Visibility timeout:            $VISIBILITY_TIMEOUT seconds"
  say "Receive message wait time:     $LONG_POLL_SECONDS seconds (long polling)"
  say "Message retention period:      4 days ($MAIN_RETENTION_SECONDS s)"
  say "Server-side encryption:        Enabled, Amazon SQS key (SSE-SQS)"
  say "Dead-letter queue:             Enabled"
  say "  Queue:                       the DLQ from the previous stage"
  say "  Maximum receives:            $MAX_RECEIVE_COUNT"
  say "Everything else:               console defaults (delay 0, 256 KB, access policy:"
  say "                               queue owner only)"
}

# dlq_attributes prints the attributes JSON for a dead-letter queue.
dlq_attributes() {
  printf '{"MessageRetentionPeriod":"%s","SqsManagedSseEnabled":"true"}' "$DLQ_RETENTION_SECONDS"
}

# main_attributes DLQ_ARN prints the attributes JSON for a work queue.
main_attributes() {
  printf '{"VisibilityTimeout":"%s","ReceiveMessageWaitTimeSeconds":"%s","MessageRetentionPeriod":"%s","SqsManagedSseEnabled":"true","RedrivePolicy":"{\\"deadLetterTargetArn\\":\\"%s\\",\\"maxReceiveCount\\":\\"%s\\"}"}' \
    "$VISIBILITY_TIMEOUT" "$LONG_POLL_SECONDS" "$MAIN_RETENTION_SECONDS" "$1" "$MAX_RECEIVE_COUNT"
}

banner "SpendTracker: SQS queues for the receipt pipeline"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "AWS account, region and environment"
command -v aws >/dev/null 2>&1 || die "The AWS CLI (v2) is not installed: https://docs.aws.amazon.com/cli/"
say "Run this with admin credentials (your own profile), not the backend's key."
say "Nothing is created in this stage."
echo
ask AWS_REGION "AWS region (the backend's AWS_REGION, e.g. us-east-1):"
while true; do
  ask QUEUE_ENV "Environment name, lowercase (e.g. dev, prod):"
  [[ "$QUEUE_ENV" =~ ^[a-z][a-z0-9-]{0,20}$ ]] && break
  warn "Use lowercase letters, digits and hyphens, starting with a letter."
done
EXTRACTION_NAME="${QUEUE_ENV}-receipt-extraction"
EXTRACTION_DLQ_NAME="${QUEUE_ENV}-receipt-extraction-dlq"
ENRICHMENT_NAME="${QUEUE_ENV}-spend-enrichment"
ENRICHMENT_DLQ_NAME="${QUEUE_ENV}-spend-enrichment-dlq"
echo
say "Credentials in use (account id, then identity):"
aws_cli sts get-caller-identity --query '[Account,Arn]' --output text \
  || die "AWS credentials are not working. Log in (aws sso login) or set AWS_PROFILE."
echo
say "Queues to be created in $AWS_REGION:"
step "$EXTRACTION_NAME   (+ $EXTRACTION_DLQ_NAME)"
step "$ENRICHMENT_NAME   (+ $ENRICHMENT_DLQ_NAME)"
echo
confirm "Is this the right account, region and environment?" || die "Stopped. Nothing was changed."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Visibility timeout"
say "While a worker processes a message, SQS hides it for the visibility timeout."
say "If the worker has not deleted it by then, SQS delivers it again."
say "So it must be LONGER than the slowest run of one stage:"
step "extraction: S3 download + Textract (a fallback may mean a second Textract call)"
step "enrichment: one Bedrock call"
say "The backend caps those calls so a stage takes at most 50 s (docs/sqs-provisioning.md),"
say "and the claim lease is 60 s, so use at least 60 s."
say "A retried message also waits this long, so keep it from being huge:"
say "$MAX_RECEIVE_COUNT attempts x timeout should stay well under the 15 minute"
say "stuck-Spend cleanup (900 s), i.e. under about 300 s."
echo
ask VISIBILITY_TIMEOUT "Visibility timeout in seconds [$DEFAULT_VISIBILITY_TIMEOUT]:"
VISIBILITY_TIMEOUT="${VISIBILITY_TIMEOUT:-$DEFAULT_VISIBILITY_TIMEOUT}"
[[ "$VISIBILITY_TIMEOUT" =~ ^[0-9]+$ ]] || die "Visibility timeout must be a whole number of seconds."
(( VISIBILITY_TIMEOUT >= 30 && VISIBILITY_TIMEOUT <= 43200 )) || die "Use between 30 and 43200 seconds."
(( VISIBILITY_TIMEOUT >= 60 )) \
  || warn "Below the 60 s claim lease, a redelivery cannot resume an interrupted stage."
(( VISIBILITY_TIMEOUT * MAX_RECEIVE_COUNT < 900 )) \
  || warn "$MAX_RECEIVE_COUNT x $VISIBILITY_TIMEOUT s reaches the 15 minute stuck-Spend cleanup."
echo
say "Using $VISIBILITY_TIMEOUT seconds for both work queues."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Extraction dead-letter queue: $EXTRACTION_DLQ_NAME"
say "Console: SQS > Create queue. Create this one BEFORE the work queue."
echo
show_dlq_settings
echo
create_queue "$EXTRACTION_DLQ_NAME" "$(dlq_attributes)"
EXTRACTION_DLQ_URL="$CREATED_URL"; EXTRACTION_DLQ_ARN="$CREATED_ARN"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Extraction queue: $EXTRACTION_NAME"
say "Console: SQS > Create queue."
echo
show_main_settings
echo
create_queue "$EXTRACTION_NAME" "$(main_attributes "$EXTRACTION_DLQ_ARN")"
EXTRACTION_URL="$CREATED_URL"; EXTRACTION_ARN="$CREATED_ARN"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Enrichment dead-letter queue: $ENRICHMENT_DLQ_NAME"
say "Console: SQS > Create queue. Create this one BEFORE the work queue."
echo
show_dlq_settings
echo
create_queue "$ENRICHMENT_DLQ_NAME" "$(dlq_attributes)"
ENRICHMENT_DLQ_URL="$CREATED_URL"; ENRICHMENT_DLQ_ARN="$CREATED_ARN"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Enrichment queue: $ENRICHMENT_NAME"
say "Console: SQS > Create queue."
echo
show_main_settings
echo
create_queue "$ENRICHMENT_NAME" "$(main_attributes "$ENRICHMENT_DLQ_ARN")"
ENRICHMENT_URL="$CREATED_URL"; ENRICHMENT_ARN="$CREATED_ARN"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "IAM policy for the backend"
POLICY_NAME="${QUEUE_ENV}-spendtracker-sqs"
POLICY_JSON=$(cat <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "sqs:SendMessage",
        "sqs:ReceiveMessage",
        "sqs:DeleteMessage",
        "sqs:ChangeMessageVisibility",
        "sqs:GetQueueAttributes",
        "sqs:GetQueueUrl"
      ],
      "Resource": [
        "$EXTRACTION_ARN",
        "$ENRICHMENT_ARN"
      ]
    }
  ]
}
POLICY
)
say "The backend sends, receives and deletes messages on the two work queues."
say "It needs no access to the dead-letter queues: SQS moves messages there itself."
say "Console: IAM > Policies > Create policy > JSON tab, name: $POLICY_NAME"
echo
printf '%s\n' "$POLICY_JSON"
echo
POLICY_ARN=$(aws_cli iam list-policies --scope Local \
  --query "Policies[?PolicyName=='$POLICY_NAME'].Arn | [0]" --output text)
if [[ "$POLICY_ARN" != "None" && -n "$POLICY_ARN" ]]; then
  warn "Policy $POLICY_NAME already exists ($POLICY_ARN); not recreated."
  note "If the queues are new, edit it in the console so its Resource list matches the JSON above."
else
  confirm "Create IAM policy $POLICY_NAME now?" || die "Not created. Re-run when ready."
  POLICY_ARN=$(aws_cli iam create-policy --policy-name "$POLICY_NAME" \
    --policy-document "$POLICY_JSON" --query Policy.Arn --output text)
  printf '  %s✓ created%s %s\n' "$GREEN" "$RESET" "$POLICY_ARN"
fi
echo
say "The backend authenticates with the IAM user behind its AWS_ACCESS_KEY_ID."
say "Console: IAM > Users > that user > Add permissions > Attach policies directly."
ask IAM_USER "IAM user name to attach the policy to (blank to attach it yourself later):"
if [[ -n "$IAM_USER" ]] && confirm "Attach $POLICY_NAME to IAM user $IAM_USER now?"; then
  aws_cli iam attach-user-policy --user-name "$IAM_USER" --policy-arn "$POLICY_ARN"
  printf '  %s✓ attached%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Attach policy $POLICY_ARN to the backend's IAM user")
fi
pause "Press Enter for the next stage"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Save the queue URLs and check the console"
say "The backend reads the work queue URLs from these environment variables."
say "(It needs no DLQ URLs.) Writing them to $ENV_FILE:"
echo
write_env SQS_RECEIPT_EXTRACTION_QUEUE_URL "$EXTRACTION_URL"
write_env SQS_SPEND_ENRICHMENT_QUEUE_URL "$ENRICHMENT_URL"
echo
note "Dead-letter queues, for reference:"
note "  $EXTRACTION_DLQ_URL"
note "  $ENRICHMENT_DLQ_URL"
echo
say "Last check: open the console and compare each queue with the settings you saw."
open_url "https://${AWS_REGION}.console.aws.amazon.com/sqs/v3/home?region=${AWS_REGION}#/queues"
step "Open each queue > Details tab, and check visibility timeout, receive wait time,"
step "retention, and (work queues) the dead-letter queue with maximum receives $MAX_RECEIVE_COUNT."
pause

finish
}

run_wizard "$@"; exit
